"""Voice lifecycle checks with generated bytes; no Telegram/provider access."""

import asyncio
import io
import json
import os
from pathlib import Path
import sqlite3
import tempfile
import threading
import time
from types import SimpleNamespace
import unittest
from unittest.mock import AsyncMock, patch

from oak.media import ToolUnavailable
from oak.sessions import SessionStore
from oak.telegram import TelegramGateway


class VoiceCleanupTests(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        folder = tempfile.TemporaryDirectory()
        self.addCleanup(folder.cleanup)
        self.root = Path(folder.name)
        self.db = sqlite3.connect(':memory:')
        self.addCleanup(self.db.close)
        self.db.execute('CREATE TABLE inputs(update_id INTEGER, status TEXT, attachments TEXT)')
        self.controller = SimpleNamespace(config={'telegram_discard_voice_audio': True},
            db=self.db, sessions=SessionStore(self.db), submit=AsyncMock(return_value=True))
        self.gateway = TelegramGateway(self.controller, 'synthetic-token', {7}, self.root)
        self.addCleanup(self.gateway.db.close)
        self.gateway._api = AsyncMock(return_value={'file_path': 'voice/file.ogg'})
        self.gateway._notice = AsyncMock()
        def download(_remote, destination, **_kwargs):
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(b'generated voice bytes')
            destination.chmod(0o600)
        self.gateway._download_sync = download

    def update(self, number=1):
        return {'update_id': number, 'message': {'chat': {'type': 'private', 'id': 7},
            'from': {'id': 7}, 'voice': {'file_id': 'synthetic', 'file_size': 21}}}

    def files(self):
        return list(self.gateway.voice_directory.glob('*'))

    async def test_accepted_voice_is_removed_after_durable_submit(self):
        async def accept(_chat, _text, update_id, attachments):
            self.assertTrue(Path(attachments[0]['path']).exists())
            self.assertTrue(attachments[0]['ephemeral_voice'])
            self.db.execute('INSERT INTO inputs VALUES (?,?,?)',
                            (update_id, 'accepted', json.dumps(attachments)))
            return True
        self.controller.submit.side_effect = accept
        await self.gateway.handle_update(self.update())
        self.assertEqual(self.files(), [])
        self.assertFalse((self.root / 'inbox').exists())

    async def test_failed_or_cancelled_transcription_removes_unaccepted_voice(self):
        for failure in (ToolUnavailable('unavailable'), asyncio.CancelledError()):
            with self.subTest(failure=type(failure).__name__):
                self.controller.submit.side_effect = failure
                try:
                    await self.gateway.handle_update(self.update(2))
                except asyncio.CancelledError:
                    pass
                self.assertEqual(self.files(), [])

    async def test_recoverable_input_survives_then_expired_orphan_is_swept(self):
        attachments = await self.gateway._attachments(self.update()['message'], 3)
        path = Path(attachments[0]['path'])
        old = time.time() - 48 * 3600
        os.utime(path, (old, old))
        self.db.execute('INSERT INTO inputs VALUES (?,?,?)', (3, 'pending', json.dumps(attachments)))
        self.gateway._release_voice_attachments(attachments)
        self.assertTrue(path.exists())
        self.assertEqual(self.gateway._cleanup_voice_cache(), 0)
        self.db.execute("UPDATE inputs SET status='accepted'")
        self.assertEqual(self.gateway._cleanup_voice_cache(), 1)
        self.assertFalse(path.exists())

    async def test_orphan_sweep_preserves_active_recent_unknown_and_linked_files(self):
        attachments = await self.gateway._attachments(self.update()['message'], 4)
        active = Path(attachments[0]['path'])
        old = time.time() - 48 * 3600
        os.utime(active, (old, old))
        unknown = active.parent / 'keep-document.txt'; unknown.write_bytes(b'keep')
        os.utime(unknown, (old, old))
        outside = self.root / 'outside.ogg'; outside.write_bytes(b'keep')
        link = active.parent / ('5-' + 'b' * 32 + '.ogg'); link.symlink_to(outside)
        orphan = active.parent / ('6-' + 'c' * 32 + '.ogg'); orphan.write_bytes(b'orphan')
        orphan.chmod(0o600)
        os.utime(orphan, (old, old))
        self.assertEqual(self.gateway._cleanup_voice_cache(), 1)
        self.assertTrue(active.exists()); self.assertTrue(unknown.exists())
        self.assertTrue(link.is_symlink()); self.assertTrue(outside.exists())
        self.assertFalse(orphan.exists())

    async def test_cancelled_thread_download_cleans_its_late_result(self):
        started, release = threading.Event(), threading.Event()
        def slow(_remote, destination, **_kwargs):
            started.set(); release.wait(2)
            destination.write_bytes(b'late generated bytes')
            destination.chmod(0o600)
        self.gateway._download_sync = slow
        task = asyncio.create_task(self.gateway._attachments(self.update()['message'], 7))
        try:
            self.assertTrue(await asyncio.to_thread(started.wait, 1))
            task.cancel()
            with self.assertRaises(asyncio.CancelledError):
                await task
            self.assertEqual(len(self.gateway._voice_downloads), 1)
        finally:
            release.set()
        for _ in range(100):
            if not self.gateway._voice_downloads:
                break
            await asyncio.sleep(0.01)
        self.assertEqual(self.gateway._voice_downloads, set())
        self.assertEqual(self.gateway._active_voice_files, set())
        self.assertEqual(self.files(), [])

    async def test_quota_reserves_inflight_download_and_metadata_cannot_bypass_stream_limit(self):
        self.gateway._voice_downloads.add(self.root / 'inflight')
        with patch('oak.telegram.VOICE_CACHE_LIMIT', 20 * 1024 * 1024), self.assertRaises(ValueError):
            await self.gateway._attachments(self.update()['message'], 8)
        self.gateway._api.assert_not_awaited()
        self.gateway._voice_downloads.clear()
        destination = self.root / 'limited.ogg'
        with patch('oak.telegram.urllib.request.build_opener') as opener:
            opener.return_value.open.return_value = io.BytesIO(b'generated-over-limit')
            with self.assertRaises(ValueError):
                TelegramGateway._download_sync(self.gateway, 'voice/file.ogg', destination, limit=4)
        self.assertFalse(destination.exists())
        self.assertEqual(list(self.root.glob('.download-*')), [])

    async def test_default_and_nonvoice_attachments_keep_existing_behavior(self):
        self.gateway.discard_voice_audio = False
        attachments = await self.gateway._attachments(self.update()['message'], 9)
        self.assertNotIn('ephemeral_voice', attachments[0])
        self.assertEqual(Path(attachments[0]['path']).parent, self.root / 'inbox')
        self.gateway.discard_voice_audio = True
        message = {'audio': {'file_id': 'synthetic', 'file_name': 'keep.mp3'}}
        attachments = await self.gateway._attachments(message, 10)
        self.assertNotIn('ephemeral_voice', attachments[0])
        self.gateway._release_voice_attachments(attachments)
        self.assertTrue(Path(attachments[0]['path']).exists())

    async def test_unreadable_recovery_state_prevents_orphan_deletion(self):
        attachments = await self.gateway._attachments(self.update()['message'], 11)
        path = Path(attachments[0]['path']); old = time.time() - 48 * 3600
        os.utime(path, (old, old))
        self.gateway._active_voice_files.clear()
        self.db.execute('DROP TABLE inputs')
        self.assertEqual(self.gateway._cleanup_voice_cache(), 0)
        self.gateway._release_voice_attachments(attachments)
        self.assertTrue(path.exists())

    async def test_malformed_recovery_attachment_structure_prevents_deletion(self):
        attachments = await self.gateway._attachments(self.update()['message'], 12)
        path = Path(attachments[0]['path']); old = time.time() - 48 * 3600
        os.utime(path, (old, old))
        self.gateway._active_voice_files.clear()
        for metadata in ('{}', '[null]', '[{}]'):
            with self.subTest(metadata=metadata):
                self.db.execute('DELETE FROM inputs')
                self.db.execute('INSERT INTO inputs VALUES (?,?,?)', (12, 'pending', metadata))
                self.assertEqual(self.gateway._cleanup_voice_cache(), 0)
                self.gateway._release_voice_attachments(attachments)
                self.assertTrue(path.exists())
